UPDATE trade_order
order_no = #{orderNo,jdbcType=VARCHAR}, request_id = #{requestId,jdbcType=VARCHAR}, user_id = #{userId,jdbcType=BIGINT}, receiver_name = #{receiverName,jdbcType=VARCHAR}, receiver_phone = #{receiverPhone,jdbcType=VARCHAR}, receiver_province = #{receiverProvince,jdbcType=VARCHAR}, receiver_city = #{receiverCity,jdbcType=VARCHAR}, receiver_district = #{receiverDistrict,jdbcType=VARCHAR}, receiver_address = #{receiverAddress,jdbcType=VARCHAR}, total_amount = #{totalAmount,jdbcType=DECIMAL}, freight_amount = #{freightAmount,jdbcType=DECIMAL}, discount_amount = #{discountAmount,jdbcType=DECIMAL}, pay_amount = #{payAmount,jdbcType=DECIMAL}, pay_expire_time = #{payExpireTime,jdbcType=TIMESTAMP}, status = #{status,jdbcType=TINYINT}, remark = #{remark,jdbcType=VARCHAR}, stock_process_status = #{stockProcessStatus,jdbcType=TINYINT},
WHERE id = #{id,jdbcType=BIGINT}

UPDATE trade_order
SET status = #{status,jdbcType=TINYINT}
WHERE id = #{id,jdbcType=BIGINT}

UPDATE trade_order
SET status = #{status,jdbcType=TINYINT}
WHERE order_no = #{orderNo,jdbcType=VARCHAR}

UPDATE trade_order
SET status = #{newStatus,jdbcType=TINYINT},
    stock_process_status = #{stockProcessStatus,jdbcType=TINYINT},
    update_time = NOW()
WHERE order_no = #{orderNo,jdbcType=VARCHAR}
  AND status = #{oldStatus,jdbcType=TINYINT}

mapper.select:
SELECT o.id, o.order_no, o.request_id, o.user_id, o.receiver_name, o.receiver_phone,
       o.receiver_province, o.receiver_city, o.receiver_district, o.receiver_address,
       o.total_amount, o.freight_amount, o.discount_amount, o.pay_amount, o.pay_expire_time,
       o.status, o.remark, o.stock_process_status, o.create_time, o.update_time
FROM trade_order o

    LEFT JOIN trade_payment_order p ON o.order_no = p.order_no



        AND o.order_no = #{orderNo}


        AND o.user_id = #{userId}


        AND o.receiver_phone LIKE CONCAT('%', #{receiverPhone}, '%')


        AND o.status = #{status}


        AND o.create_time >= #{createTimeStart}


        AND o.create_time <= #{createTimeEnd}


        AND o.pay_amount >= #{payAmountMin}


        AND o.pay_amount <= #{payAmountMax}


        AND p.pay_channel = #{payChannel}


        AND p.status = #{paymentStatus}


ORDER BY o.create_time DESC

SELECT COUNT(*) AS orderCount, COALESCE(SUM(pay_amount), 0) AS orderAmount
FROM trade_order
WHERE create_time >= #{todayStart}

SELECT COUNT(*)
FROM trade_order
WHERE status = #{status}
